/**
 * Every live issue of a project in number order, with its label ids: the rows
 * a clone copies. Deliberately unpaged, because a clone has to walk the whole
 * project rather than one page of it.
 */
export async function listIssuesForClone(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const db = getDb();
  const rows = db
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  // One join for every label of the project, not an `IN (...)` over every
  // issue id, which would outgrow SQLite's bound-parameter limit on big projects.
  const labelRows = db
    .select({ issueId: issueLabels.issueId, labelId: issueLabels.labelId })
    .from(issueLabels)
    .innerJoin(issues, eq(issues.id, issueLabels.issueId))
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issues.projectId, projectId),
        isNull(issues.archivedAt),
      ),
    )
    .all();

  const labelsByIssue = new Map<string, LabelId[]>();
  for (const label of labelRows) {
    const bucket = labelsByIssue.get(label.issueId) ?? [];
    bucket.push(label.labelId as LabelId);
    labelsByIssue.set(label.issueId, bucket);
  }

  return rows.map((row) => toIssue(row, labelsByIssue.get(row.id) ?? []));
}

