export interface InsertCloneInput {
  readonly orgId: OrgId;
  readonly source: Project;
  readonly name: string;
  readonly slug: string;
  readonly key: string;
  readonly authorId: UserId;
  readonly defaultStatus: IssueStatus;
  /** Live issues of the source, in the order their copies should be numbered. */
  readonly issues: readonly Issue[];
}

/**
 * Writes a clone in one transaction: the project row, then each copied issue
 * numbered 1..n with its labels. Either all of it lands or none of it does.
 *
 * The clone keeps the source's description, visibility, colour and lead, and
 * starts `active` with no dates. Each copy starts in `defaultStatus`,
 * unassigned and unstarted, authored by `authorId`, with no parent.
 */
export async function insertClone(
  input: InsertCloneInput,
): Promise<{ project: Project; issues: readonly Issue[] }> {
  const slug = uniqueSlug(input.slug, await listTakenProjectSlugs(input.orgId));
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    const projectRow = tx
      .insert(projects)
      .values({
        id: newId(),
        orgId: input.orgId,
        name: input.name,
        slug,
        key: input.key,
        description: input.source.description,
        visibility: input.source.visibility,
        status: "active",
        leadId: input.source.leadId,
        color: input.source.color,
        startsAt: null,
        targetDate: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    const copies = input.issues.map((source, index) => {
      const id = newId();
      const row = tx
        .insert(issues)
        .values({
          id,
          orgId: input.orgId,
          projectId: projectRow.id,
          number: index + 1,
          title: source.title,
          description: source.description,
          status: input.defaultStatus,
          priority: source.priority,
          authorId: input.authorId,
          assigneeId: null,
          parentId: null,
          estimate: source.estimate,
          dueAt: source.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (source.labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            source.labelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: id,
              labelId,
            })),
          )
          .run();
      }

      return toIssue(row, source.labelIds);
    });

    return { project: toProject(projectRow), issues: copies };
  });
}

/** Includes archived slugs — a restored project must not collide. */

