/**
 * Clones a project into the same workspace under the caller's name, slug and
 * key, optionally with its live issues (never their comments or attachments).
 *
 * Gates run before anything is written: `project:read` on the live source,
 * `project:create` on the workspace, the plan's project quota and the plan's
 * per-project issue quota for the whole batch of copies.
 *
 * A clone announces itself with one `project.cloned` event rather than
 * `project.created` plus one `issue.created` per copy, so the search index and
 * usage meters are brought up to date here.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:read", projectResource(source));
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const usedProjects = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", usedProjects)) {
    throw new Error(
      `Plan ${org.plan} allows ${usedProjects} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listIssuesForClone(input.orgId, source.id)
    : [];

  // The clone is a new project, so its per-project count starts at zero.
  if (wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)) {
    throw new Error(
      `Plan ${org.plan} allows ${getLimit(org.plan, "issuesPerProject")} issues per project; cloning ${source.key} would copy ${sourceIssues.length}`,
    );
  }

  const parsedStatus = issueStatusSchema.safeParse(
    org.settings.defaultIssueStatus,
  );
  const defaultStatus: IssueStatus = parsedStatus.success
    ? parsedStatus.data
    : "backlog";

  const { project, issues: copies } = await projectRepo.insertClone({
    orgId: input.orgId,
    source,
    name: input.name,
    slug: input.slug,
    key: input.key,
    authorId: actor.userId,
    defaultStatus,
    issues: sourceIssues,
  });

  await indexProject(input.orgId, project);
  for (const issue of copies) {
    await indexIssue(input.orgId, issue);
  }
  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: copies.length,
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return project;
}

