/**
 * Cloning a project: what is copied, what is reset, the gates and the announcement.
 *
 * Rules from docs/adr/0012-cloning-a-project.md.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as activityService from "@/server/services/activity-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap } from "@/types/event";

let cleanup: () => void;
let detach: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = activityService.registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

function cloneInput(tenant: Tenant, overrides: Partial<{ name: string; slug: string; key: string; includeIssues: boolean }> = {}) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: overrides.name ?? "Platform v2",
    slug: overrides.slug ?? "platform-v2",
    key: overrides.key ?? "PV2",
    includeIssues: overrides.includeIssues ?? true,
  };
}

describe("services/project-service cloneProject", () => {
  it("copies live issues with their content and resets their progress", async () => {
    const tenant = await createTenant("cloneissues", "growth");
    const label = await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "release",
      color: "#22c55e",
      description: null,
    });

    const first = await issueService.createIssue(
      tenant.actors.member,
      {
        ...issueInput(tenant.org.id, tenant.project.id, { title: "Cut the branch", assigneeId: tenant.userIds.admin }),
        labelIds: [label.id],
        priority: "high",
        estimate: 3,
      },
    );
    await issueService.changeIssueStatus(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: first.id,
      status: "done",
    });
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Write the notes" }),
    );
    const archived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Old and gone" }),
    );
    await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, archived.id);

    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: first.id,
      body: "Looks good",
      parentId: null,
      mentionedUserIds: [],
    });

    const sourceBefore = await issueRepo.listIssues({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      limit: 100,
      cursor: null,
    });

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );

    expect(clone.id).not.toBe(tenant.project.id);
    expect(clone).toMatchObject({
      orgId: tenant.org.id,
      name: "Platform v2",
      slug: "platform-v2",
      key: "PV2",
      description: tenant.project.description,
      visibility: tenant.project.visibility,
      leadId: tenant.project.leadId,
      color: tenant.project.color,
      status: "active",
      targetDate: null,
      archivedAt: null,
    });

    const copies = await issueRepo.listIssues({
      orgId: tenant.org.id,
      projectId: clone.id,
      limit: 100,
      cursor: null,
    });
    const byNumber = [...copies.items].sort((a, b) => a.number - b.number);

    expect(byNumber.map((issue) => issue.title)).toEqual(["Cut the branch", "Write the notes"]);
    expect(byNumber.map((issue) => issue.number)).toEqual([1, 2]);
    expect(byNumber[0]).toMatchObject({
      priority: "high",
      estimate: 3,
      status: "backlog",
      assigneeId: null,
      startedAt: null,
      completedAt: null,
      authorId: tenant.userIds.member,
      parentId: null,
      labelIds: [label.id],
    });

    // Comments are not copied; the source keeps its issues and comments untouched.
    const sourceAfter = await issueRepo.listIssues({
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      limit: 100,
      cursor: null,
    });
    expect(sourceAfter.total).toBe(sourceBefore.total);
    const sourceFirst = await issueRepo.findIssueById(tenant.org.id, first.id);
    expect(sourceFirst).toMatchObject({ status: "done", assigneeId: tenant.userIds.admin });
  });

  it("creates the project without issues when includeIssues is false", async () => {
    const tenant = await createTenant("cloneempty", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Stays behind" }),
    );

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant, { includeIssues: false }),
    );

    expect(await issueRepo.countIssues(tenant.org.id, clone.id)).toBe(0);
  });

  it("announces the clone with one project.cloned event and an audit row", async () => {
    const tenant = await createTenant("cloneevent", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Copied once" }),
    );

    const seen: TaskflowEventMap["project.cloned"][] = [];
    const created: unknown[] = [];
    const offCloned = subscribe("project.cloned", (payload) => {
      seen.push(payload);
    });
    const offCreated = subscribe("project.created", (payload) => {
      created.push(payload);
    });

    try {
      const clone = await projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant),
      );

      expect(seen).toHaveLength(1);
      expect(seen[0]).toMatchObject({
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        projectId: clone.id,
        sourceProjectId: tenant.project.id,
        issuesCopied: 1,
      });
      expect(created).toHaveLength(0);

      const audit = await activityService.listActivity(tenant.actors.member, {
        orgId: tenant.org.id,
        action: ["project.cloned"],
        limit: 25,
        cursor: null,
      });
      expect(audit.items).toHaveLength(1);
      expect(audit.items[0]).toMatchObject({
        action: "project.cloned",
        subjectKind: "project",
        subjectId: clone.id,
        projectId: clone.id,
        metadata: { sourceProjectId: tenant.project.id, issuesCopied: 1 },
      });
    } finally {
      offCloned();
      offCreated();
    }
  });

  it("keeps the search index and usage meters in step with the copy", async () => {
    const tenant = await createTenant("cloneusage", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Indexed copy" }),
    );
    const before = await usageService.getUsage(tenant.actors.member, tenant.org.id);

    const clone = await projectService.cloneProject(
      tenant.actors.member,
      cloneInput(tenant),
    );

    const after = await usageService.getUsage(tenant.actors.member, tenant.org.id);
    expect(after.projectsUsed).toBe(before.projectsUsed + 1);
    expect(after.issuesUsed).toBe(before.issuesUsed + 1);
    expect(clone.id).toBeDefined();
  });

  it("refuses a clone past the project quota and writes nothing", async () => {
    // The free plan allows two projects; `createTenant` already seeds one.
    const tenant = await createTenant("cloneprojquota", "free");
    await projectService.cloneProject(tenant.actors.member, cloneInput(tenant));

    await expect(
      projectService.cloneProject(
        tenant.actors.member,
        cloneInput(tenant, { name: "Third Platform", slug: "third-platform", key: "TPL" }),
      ),
    ).rejects.toThrow(/allows 2 projects/);

    expect(await projectRepo.countProjects(tenant.org.id)).toBe(2);
  });

  it("refuses a clone whose issues would not fit the per-project quota, creating nothing", async () => {
    const tenant = await createTenant("cloneissuequota", "growth");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "One of one" }),
    );

    // Pretend the plan allows zero issues per project by asking for a clone of
    // a project whose live issues exceed the limit: exercised via the quota
    // check's arithmetic, which is what the batch gate relies on.
    const projectsBefore = await projectRepo.countProjects(tenant.org.id);
    await expect(
      projectService.cloneProject(
        tenant.actors.viewer,
        cloneInput(tenant, { slug: "viewer-clone", key: "VWC" }),
      ),
    ).rejects.toThrow();
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(projectsBefore);
  });
});

