it("refuses a clone whose batch of issues exceeds the per-project quota, creating nothing", async () => {
  // The free plan allows 100 issues per project. The service would never let
  // the source get past that, so the source is filled through the repository.
  const tenant = await createTenant("cloneissuequota", "free");
  for (let number = 1; number <= 101; number += 1) {
    await issueRepo.insertIssue(
      issueInput(tenant.org.id, tenant.project.id, { title: `Bulk issue ${number}` }),
      tenant.userIds.member,
      number,
    );
  }

  await expect(
    projectService.cloneProject(tenant.actors.member, cloneInput(tenant)),
  ).rejects.toThrow(/allows 100 issues per project/);

  expect(await projectRepo.countProjects(tenant.org.id)).toBe(1);
  expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(101);
});

