function cloneInput(tenant: Tenant, overrides: Partial<{ name: string; slug: string; key: string; includeIssues: boolean }> = {}) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    name: overrides.name ?? "Platform v2",
    slug: overrides.slug ?? "platform-v2",
    key: overrides.key ?? "PV2",
    includeIssues: overrides.includeIssues ?? true,
  };
}

